source:
'use client';

import React, { useEffect, useState, useCallback, memo, useRef } from 'react';
import api from '@/services/api';
import { useAuth } from '@/context/AuthContext';
import { toast } from 'sonner';
import { ConfirmDialog } from '@/components/ui/ConfirmDialog';
import { cn } from '@/lib/utils';
import {
  Search,
  Plus,
  Package,
  ChevronLeft,
  ChevronRight,
  Filter,
  ArrowUpDown,
  X,
  Loader2,
  Trash2,
  Edit2,
  Box,
  Image as ImageIcon,
  Upload,
  Save,
  AlertCircle,
  LayoutList,
  LayoutGrid,
  ChevronDown,
  RotateCcw
} from 'lucide-react';


// --- Types ---
interface Product {
  id: number;
  name: string;
  price: number;
  currentStock: number;
  imageUrl: string;
  versionStamp: string;
  stockVersionStamp: string;
  categoryId?: number;
  categoryName?: string;
}

interface Category {
  categoryId: number;
  categoryName: string;
  description?: string;
  parentCategoryId?: number;
  subCategories: Category[];
}

const formatCurrency = (value: number) => {
  return `${(value || 0).toLocaleString()} MMK`;
};

const CategoryOptions = ({ categories, level = 0 }: { categories: Category[], level?: number }) => (
  <>
    {categories.map(cat => (
      <React.Fragment key={cat.categoryId}>
        <option value={cat.categoryId}>
          {"\u00A0".repeat(level * 4)}{cat.categoryName}
        </option>
        {cat.subCategories && cat.subCategories.length > 0 && (
          <CategoryOptions categories={cat.subCategories} level={level + 1} />
        )}
      </React.Fragment>
    ))}
  </>
);

// --- Memoized Row ---
const InventoryRow = memo(({ product, index, onSelect, onDelete }: {
  product: Product,
  index: number,
  onSelect: (p: Product) => void,
  onDelete: (id: number, version: string) => void
}) => (
  <tr
    onClick={() => onSelect(product)}
    className="group hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors cursor-pointer border-b border-zinc-200 dark:border-zinc-700 last:border-0"
  >
    <td className="px-4 py-3 text-[10px] font-bold text-zinc-400 w-12 text-center border-r border-zinc-200 dark:border-zinc-700">
      {index}
    </td>
    <td className="px-4 py-3">
      <div className="flex items-center gap-3">
        <div className="w-9 h-9 rounded bg-zinc-100 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 flex items-center justify-center overflow-hidden shrink-0 shadow-sm">
          {product.imageUrl ? <img src={product.imageUrl} alt="" className="w-full h-full object-cover" /> : <Package size={14} className="text-zinc-400" />}
        </div>
        <div>
          <p className="text-xs font-semibold text-zinc-900 dark:text-zinc-100 truncate tracking-tight">{product.name}</p>
          <div className="flex items-center gap-2 mt-0.5">
            <p className="text-[10px] text-zinc-400 font-medium">ID: {product.id.toString().padStart(5, '0')}</p>
            {product.categoryName && (
              <span className="text-[9px] px-1.5 py-0.5 bg-zinc-100 dark:bg-zinc-800 text-zinc-500 dark:text-zinc-400 rounded-md font-bold uppercase tracking-wider border border-zinc-200/50 dark:border-zinc-700/50">
                {product.categoryName}
              </span>
            )}
          </div>
        </div>
      </div>
    </td>
    <td className="px-4 py-3 text-right text-xs font-semibold text-zinc-900 dark:text-zinc-100">
      {formatCurrency(product.price)}
    </td>
    <td className="px-4 py-3 text-right">
      <div className={cn(
        "inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-tighter",
        product.currentStock > 5 ? "bg-emerald-50 dark:bg-emerald-500/10 text-emerald-700 dark:text-emerald-400" : "bg-amber-50 dark:bg-amber-500/10 text-amber-700 dark:text-amber-400"
      )}>
        {product.currentStock} Units
      </div>
    </td>
    <td className="px-4 py-3 text-right">
      <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        <button className="p-1.5 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100 transition-colors">
          <Edit2 size={12} />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onDelete(product.id, product.versionStamp); }}
          className="p-1.5 hover:bg-rose-50 dark:hover:bg-rose-500/10 rounded text-zinc-400 hover:text-rose-600 dark:hover:text-rose-400 transition-colors"
        >
          <Trash2 size={12} />
        </button>
      </div>
    </td>
  </tr>
));
InventoryRow.displayName = 'InventoryRow';

const InventoryCard = memo(({ product, index, onSelect, onDelete }: {
  product: Product,
  index: number,
  onSelect: (p: Product) => void,
  onDelete: (id: number, version: string) => void
}) => (
  <div
    onClick={() => onSelect(product)}
    onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onSelect(product); } }}
    role="button"
    tabIndex={0}
    className="group bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-700 rounded-xl p-4 hover:shadow-md transition-all cursor-pointer relative overflow-hidden flex flex-col h-full"
  >
    <div className="absolute top-2 right-2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity z-10">
      <button className="p-1.5 bg-white dark:bg-zinc-900/80 backdrop-blur-sm border border-zinc-200 dark:border-zinc-700 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded shadow-sm text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100 transition-colors">
        <Edit2 size={10} />
      </button>
      <button
        onClick={(e) => { e.stopPropagation(); onDelete(product.id, product.versionStamp); }}
        className="p-1.5 bg-white dark:bg-zinc-900/80 backdrop-blur-sm border border-zinc-200 dark:border-zinc-700 hover:bg-rose-50 rounded shadow-sm text-zinc-400 hover:text-rose-600 transition-colors"
      >
        <Trash2 size={10} />
      </button>
    </div>

    <div className="w-full h-32 bg-zinc-50 dark:bg-zinc-900/50 rounded-lg border border-zinc-200 dark:border-zinc-700 flex items-center justify-center overflow-hidden mb-4 relative">
      <div className="absolute top-2 left-2 w-6 h-6 bg-white dark:bg-zinc-900/80 backdrop-blur-sm border border-zinc-200 dark:border-zinc-700 rounded-full flex items-center justify-center text-[10px] font-bold text-zinc-400 shadow-sm">
        {index}
      </div>
      {product.imageUrl ? (
        <img src={product.imageUrl} alt="" className="w-full h-full object-contain p-2" />
      ) : (
        <Package size={32} className="text-zinc-200" />
      )}
    </div>

    <div className="space-y-1 mb-4 flex-1">
      <div className="flex items-start justify-between gap-2">
        <p className="text-[10px] font-bold text-zinc-900 dark:text-zinc-100 tracking-tight line-clamp-1 flex-1">{product.name}</p>
        {product.categoryName && (
          <span className="text-[8px] px-1 bg-zinc-100 dark:bg-zinc-800 text-zinc-400 font-bold uppercase rounded border border-zinc-200 dark:border-zinc-700 shrink-0">
            {product.categoryName}
          </span>
        )}
      </div>
      <p className="text-[9px] text-zinc-400 font-semibold uppercase tracking-widest">ID: {product.id.toString().padStart(5, '0')}</p>
    </div>

    <div className="flex items-center justify-between pt-3 border-t border-zinc-50 mt-auto">
      <p className="text-xs font-bold text-zinc-900 dark:text-zinc-100">{formatCurrency(product.price)}</p>
      <div className={cn(
        "px-2 py-0.5 rounded text-[9px] font-bold uppercase tracking-tighter",
        product.currentStock > 5 ? "bg-emerald-50 dark:bg-emerald-500/10 text-emerald-700 dark:text-emerald-400" : "bg-amber-50 dark:bg-amber-500/10 text-amber-700 dark:text-amber-400"
      )}>
        {product.currentStock} Units
      </div>
    </div>
  </div>
));
InventoryCard.displayName = 'InventoryCard';

// --- Optimized Detail Modal ---
const ProductDetailModal = ({ product, onClose, onUpdate, onDelete, onEditSuccess, categories, categoryTree }: {
  product: Product,
  onClose: () => void,
  onUpdate: () => void,
  onDelete: (id: number, version: string) => void,
  onEditSuccess: (updated: Product) => void,
  categories: Category[],
  categoryTree: Category[]
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [editForm, setEditForm] = useState({
    name: product.name,
    price: product.price.toString(),
    categoryId: product.categoryId?.toString() || ''
  });
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isUploadingImage, setIsUploadingImage] = useState(false);
  const imageInputRef = useRef<HTMLInputElement>(null);

  // Sync form ONLY when NOT editing (e.g. after background refresh or on mount)
  useEffect(() => {
    if (!isEditing) {
      setEditForm({
        name: product.name,
        price: product.price.toString(),
        categoryId: product.categoryId?.toString() || ''
      });
    }
  }, [product, isEditing]);

  // Stock Update State
  const [newStock, setNewStock] = useState(product.currentStock.toString());
  const [isUpdatingStock, setIsUpdatingStock] = useState(false);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      const reader = new FileReader();
      reader.onloadend = () => setImagePreview(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleReplaceImage = async () => {
    if (!imageFile) return;
    setIsUploadingImage(true);
    try {
      const formData = new FormData();
      formData.append('Id', product.id.toString());
      formData.append('Name', product.name);
      formData.append('Price', product.price.toString());
      formData.append('VersionStamp', product.versionStamp);
      if (product.stockVersionStamp) {
        formData.append('StockVersionStamp', product.stockVersionStamp);
      }
      if (product.categoryId) {
        formData.append('CategoryId', product.categoryId.toString());
      }
      formData.append('photoFile', imageFile);

      const response = await api.put('/inventories', formData);
      if (response.data.isSuccess) {
        setImageFile(null);
        setImagePreview(null);
        onUpdate();
      }
    } catch (error: any) {
      console.error('Failed to upload image:', error);
      toast.error(error.response?.data?.message || 'Image upload failed');
    } finally {
      setIsUploadingImage(false);
    }
  };

  const handleSaveInfo = async () => {
    const parsedPrice = Number.parseFloat(editForm.price);
    if (Number.isNaN(parsedPrice) || parsedPrice < 0) {
      toast.error("Price cannot be negative.");
      return;
    }
    setIsSubmitting(true);
    try {
      const formData = new FormData();
      formData.append('Id', product.id.toString());
      formData.append('Name', editForm.name);
      formData.append('Price', editForm.price);
      if (editForm.categoryId) {
        formData.append('CategoryId', editForm.categoryId);
      }
      formData.append('VersionStamp', product.versionStamp);
      if (product.stockVersionStamp) {
        formData.append('StockVersionStamp', product.stockVersionStamp);
      }

      const response = await api.put('/inventories', formData);
      if (response.data.isSuccess) {
        // OPTIMISTIC/IMMEDIATE UPDATE
        onEditSuccess({
          ...product,
          name: editForm.name,
          price: Number.parseFloat(editForm.price),
          categoryId: editForm.categoryId ? Number.parseInt(editForm.categoryId, 10) : undefined,
          categoryName: categories.find(c => c.categoryId.toString() === editForm.categoryId)?.categoryName
        });
        setIsEditing(false);
        onUpdate(); // Trigger background sync
      }
    } catch (error: any) {
      console.error('Failed to update product:', error);
      toast.error(error.response?.data?.message || 'Update failed');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleUpdateStock = async () => {
    const parsedStock = Number.parseInt(newStock, 10);
    if (Number.isNaN(parsedStock) || parsedStock < 0) {
      toast.error("Stock quantity cannot be negative.");
      return;
    }
    setIsUpdatingStock(true);
    try {
      const response = await api.post('/inventories/update-stock', {
        inventoryId: product.id,
        currentStock: Number.parseInt(newStock, 10),
        stockVersionStamp: product.stockVersionStamp
      });
      if (response.data.isSuccess) {
        // Immediate visual update for stock
        onEditSuccess({
          ...product,
          currentStock: Number.parseInt(newStock, 10)
        });
        onUpdate();
        onClose();
      }
    } catch (error: any) {
      console.error('Failed to update stock:', error);
      toast.error(error.response?.data?.message || 'Stock update failed');
    } finally {
      setIsUpdatingStock(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 overflow-hidden">
      <div className="absolute inset-0 bg-zinc-900/40 backdrop-blur-sm animate-in fade-in duration-150" onClick={onClose} role="button" tabIndex={-1} aria-label="Close modal" onKeyDown={(e) => { if (e.key === 'Escape') onClose(); }}></div>
      <div className="relative bg-white dark:bg-zinc-900 w-full max-w-xl rounded-xl shadow-2xl animate-in zoom-in-98 duration-150 flex flex-col max-h-[95vh]">

        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-zinc-200 dark:border-zinc-700">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 bg-zinc-900 dark:bg-zinc-100 rounded-lg flex items-center justify-center">
              <Box size={14} className="text-white dark:text-zinc-900" />
            </div>
            <h3 className="text-[10px] font-bold text-zinc-900 dark:text-zinc-100 uppercase tracking-widest">Management Console</h3>
          </div>
          <div className="flex items-center gap-2">
            {!isEditing && (
              <button
                onClick={() => setIsEditing(true)}
                className="flex items-center gap-1.5 px-3 py-1 bg-zinc-100 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 rounded text-[10px] font-bold text-zinc-600 dark:text-zinc-400 uppercase hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-all"
              >
                <Edit2 size={10} />
                Update Product
              </button>
            )}
            <button onClick={onClose} className="p-1 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-md transition-colors">
              <X size={16} className="text-zinc-400" />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-10">
          {/* Section 1: Basic Info */}
          <div className="space-y-6">
            <div className="flex items-center gap-2">
              <div className="w-1.5 h-4 bg-zinc-900 rounded-full" />
              <h4 className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">Core Product Specifications</h4>
            </div>

            <div className="flex flex-col sm:flex-row gap-6 sm:gap-8 items-center sm:items-start relative w-full">
              <div className="w-24 h-24 rounded-xl bg-zinc-50 dark:bg-zinc-900/50 border border-zinc-200 dark:border-zinc-700 flex items-center justify-center overflow-hidden shrink-0 shadow-inner group relative">
                {imagePreview ? (
                  <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
                ) : product.imageUrl ? (
                  <img src={product.imageUrl} alt="" className="w-full h-full object-cover" />
                ) : (
                  <ImageIcon size={24} className="text-zinc-300" />
                )}
                <input type="file" ref={imageInputRef} accept="image/*" className="hidden" onChange={handleImageSelect} />
                <div
                  onClick={() => imageInputRef.current?.click()}
                  onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); imageInputRef.current?.click(); } }}
                  role="button"
                  tabIndex={0}
                  className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center cursor-pointer gap-1"
                >
                  <Upload size={14} className="text-white" />
                  <span className="text-[8px] font-bold text-white uppercase">Replace</span>
                </div>
              </div>
              {imageFile && (
                <div className="absolute -bottom-8 left-0">
                  <button
                    onClick={handleReplaceImage}
                    disabled={isUploadingImage}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-600 text-white text-[9px] font-bold uppercase tracking-widest rounded-lg hover:bg-emerald-700 disabled:opacity-50 transition-all shadow-md"
                  >
                    {isUploadingImage ? <Loader2 size={10} className="animate-spin" /> : <Upload size={10} />}
                    {isUploadingImage ? 'Uploading...' : 'Save Photo'}
                  </button>
                </div>
              )}
              <div className="flex-1 space-y-4">
                {isEditing ? (
                  <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="space-y-1.5">
                      <span className="block text-[9px] font-bold text-zinc-400 uppercase">Product Name</span>
                      <input
                        autoFocus
                        value={editForm.name}
                        onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}
                        className="w-full text-base font-semibold text-zinc-900 dark:text-zinc-100 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-lg px-4 py-2 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 placeholder:text-zinc-300 dark:placeholder:text-zinc-600 transition-all"
                      />
                    </div>
                    <div className="space-y-1.5">
                      <span className="block text-[9px] font-bold text-zinc-400 uppercase">Unit Price (MMK)</span>
                      <div className="relative">
                        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[10px] font-bold text-zinc-400">MMK</span>
                        <input
                          type="number"
                          min="0"
                          value={editForm.price}
                          onChange={(e) => setEditForm({ ...editForm, price: e.target.value })}
                          className="w-full pl-14 pr-4 py-2 text-base font-semibold text-zinc-900 dark:text-zinc-100 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-lg outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 placeholder:text-zinc-300 dark:placeholder:text-zinc-600 transition-all"
                        />
                      </div>
                    </div>
                    <div className="space-y-1.5">
                      <span className="block text-[9px] font-bold text-zinc-400 uppercase">Category</span>
                      <select
                        value={editForm.categoryId}
                        onChange={(e) => setEditForm({ ...editForm, categoryId: e.target.value })}
                        className="w-full text-xs font-semibold text-zinc-900 dark:text-zinc-100 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-lg px-4 py-2 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 transition-all appearance-none"
                      >
                        <option value="">Uncategorized</option>
                        <CategoryOptions categories={categoryTree} />
                      </select>
                    </div>
                    <div className="flex gap-2 pt-2">
                      <button onClick={handleSaveInfo} disabled={isSubmitting} className="flex-1 py-2.5 bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 text-[10px] font-bold uppercase tracking-widest rounded-lg hover:bg-zinc-800 dark:hover:bg-zinc-200 disabled:opacity-50 shadow-lg dark:shadow-black/20 shadow-zinc-100 flex items-center justify-center gap-2">
                        {isSubmitting ? <><Loader2 size={12} className="animate-spin" /> Syncing...</> : <><Save size={12} /> Commit Changes</>}
                      </button>
                      <button onClick={() => setIsEditing(false)} className="px-6 py-2.5 bg-white dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 text-zinc-500 dark:text-zinc-400 text-[10px] font-bold uppercase tracking-widest rounded-lg hover:bg-zinc-100 dark:hover:bg-zinc-700">Cancel</button>
                    </div>
                  </div>
                ) : (
                  <div className="space-y-2">
                    <h2 className="text-2xl font-bold text-zinc-900 dark:text-zinc-100 tracking-tight leading-none">{product.name}</h2>
                    <div className="flex items-baseline gap-2">
                      <p className="text-lg font-bold text-emerald-600 tracking-tight">{formatCurrency(product.price)}</p>
                      <p className="text-[10px] text-zinc-400 font-semibold uppercase tracking-widest">Per Unit</p>
                    </div>
                    <div className="flex items-center gap-3 pt-2">
                      <div className="flex items-center gap-1.5 px-2 py-1 bg-zinc-100 dark:bg-zinc-800 rounded text-[9px] font-bold text-zinc-500 uppercase tracking-widest">
                        PROD-{product.id.toString().padStart(6, '0')}
                      </div>
                      <div className="flex items-center gap-1.5 px-2 py-1 bg-zinc-100 dark:bg-zinc-800 rounded text-[9px] font-bold text-zinc-500 uppercase tracking-widest">
                        Ver: {product.versionStamp?.substring(0, 6)}
                      </div>
                      {product.categoryName && (
                        <div className="flex items-center gap-1.5 px-2 py-1 bg-emerald-50 dark:bg-emerald-500/10 rounded text-[9px] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-widest border border-emerald-200/50 dark:border-emerald-500/20">
                          {product.categoryName}
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          <hr className="border-zinc-50" />

          {/* Section 2: Stock Management */}
          <div className="space-y-6">
            <div className="flex items-center gap-2">
              <div className="w-1.5 h-4 bg-emerald-500 rounded-full" />
              <h4 className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">Inventory Asset Control</h4>
            </div>

            <div className="p-6 bg-zinc-50 dark:bg-zinc-900/50 border border-zinc-200 dark:border-zinc-700 rounded-2xl space-y-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">Live Inventory Level</p>
                  <p className="text-3xl font-bold text-zinc-900 dark:text-zinc-100 tracking-tighter mt-1">{product.currentStock} <span className="text-sm text-zinc-400">Units</span></p>
                </div>
                <div className={cn(
                  "px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest",
                  product.currentStock > 10 ? "bg-emerald-100 dark:bg-emerald-500/15 text-emerald-700 dark:text-emerald-400" : "bg-amber-100 dark:bg-amber-500/15 text-amber-700 dark:text-amber-400"
                )}>
                  {product.currentStock > 10 ? 'Healthy Stock' : 'Low Inventory'}
                </div>
              </div>

              <div className="flex flex-col sm:flex-row sm:items-end gap-3 sm:gap-4 border-t border-zinc-200 dark:border-zinc-700 pt-6">
                 <div className="w-full sm:flex-1 space-y-2">
                   <span className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest">Manual Override Value</span>
                  <input
                    type="number"
                    min="0"
                    step="1"
                    value={newStock}
                    onChange={(e) => setNewStock(e.target.value)}
                    className="w-full px-4 py-3 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-700 rounded-xl font-bold text-zinc-900 dark:text-zinc-100 outline-none focus:ring-1 focus:ring-emerald-500 transition-all text-xl"
                  />
                </div>
                <button
                  disabled={isUpdatingStock || newStock === product.currentStock.toString()}
                  onClick={handleUpdateStock}
                  className="w-full sm:w-auto px-8 py-3.5 bg-emerald-600 text-white text-[10px] font-bold uppercase tracking-widest rounded-xl hover:bg-emerald-700 disabled:opacity-20 transition-all shadow-xl dark:shadow-black/20 shadow-emerald-100 flex items-center justify-center gap-2"
                >
                  {isUpdatingStock ? <><Loader2 size={12} className="animate-spin" /> Syncing...</> : 'Update Asset'}
                </button>
              </div>

              <div className="flex items-center gap-2 px-1 text-[10px] text-zinc-400 font-semibold">
                <AlertCircle size={12} className="text-amber-500" />
                Adjustments are recorded for financial audit trails.
              </div>
            </div>
          </div>
        </div>

        <div className="p-4 bg-zinc-50 dark:bg-zinc-900/50 border-t border-zinc-200 dark:border-zinc-700 flex items-center justify-between">
          <button disabled={isDeleting} onClick={() => { setIsDeleting(true); onDelete(product.id, product.versionStamp); setIsDeleting(false); }} className="px-4 py-2 text-[10px] font-bold text-rose-600 dark:text-rose-400 uppercase tracking-widest hover:bg-rose-50 dark:hover:bg-rose-500/10 rounded-lg transition-all disabled:opacity-50 flex items-center gap-2">{isDeleting ? <><Loader2 size={12} className="animate-spin" /> Archiving...</> : 'Archive Product'}</button>
          <span className="text-[9px] text-zinc-400 font-semibold uppercase tracking-widest opacity-50">Confidential • Enterprise Product Record</span>
        </div>
      </div>
    </div>
  );
};

// --- Main Page ---
export default function InventoryPage() {
  const { currentBusinessId } = useAuth();
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchInput, setSearchInput] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [searchTrigger, setSearchTrigger] = useState(0);
  const [viewType, setViewType] = useState<'table' | 'grid'>('table');
  const [productToDelete, setProductToDelete] = useState<{ id: number, version: string } | null>(null);

  // Filter state
  const [showFilters, setShowFilters] = useState(false);
  const [filterCategoryId, setFilterCategoryId] = useState('');
  const [filterMinPrice, setFilterMinPrice] = useState('');
  const [filterMaxPrice, setFilterMaxPrice] = useState('');
  const [filterMinStock, setFilterMinStock] = useState('');
  const [filterMaxStock, setFilterMaxStock] = useState('');
  const [filterSortBy, setFilterSortBy] = useState<'name' | 'price' | 'createdDate'>('name');
  const [filterSortDesc, setFilterSortDesc] = useState(false);
  const [lowStockOnly, setLowStockOnly] = useState(false);

  const hasActiveFilters = filterCategoryId || filterMinPrice || filterMaxPrice || filterMinStock || filterMaxStock || filterSortBy !== 'name' || filterSortDesc;

  const resetFilters = () => {
    setFilterCategoryId('');
    setFilterMinPrice('');
    setFilterMaxPrice('');
    setFilterMinStock('');
    setFilterMaxStock('');
    setFilterSortBy('name');
    setFilterSortDesc(false);
    setPage(1);
  };

  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newProduct, setNewProduct] = useState({ name: '', price: '', stock: '', categoryId: '' });
  const [newProductImage, setNewProductImage] = useState<File | null>(null);
  const [newProductImagePreview, setNewProductImagePreview] = useState<string | null>(null);
  const addImageInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (selectedProduct || isAddModalOpen || productToDelete) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => {
      document.body.style.overflow = '';
    };
  }, [selectedProduct, isAddModalOpen, productToDelete]);

  const [categoryTree, setCategoryTree] = useState<Category[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);

  const fetchCategories = useCallback(async () => {
    try {
      const [treeRes, flatRes] = await Promise.all([
        api.get('/categories/tree'),
        api.get('/categories')
      ]);
      if (treeRes.data.isSuccess) setCategoryTree(treeRes.data.data);
      if (flatRes.data.isSuccess) setCategories(flatRes.data.data);
    } catch (error) {
      console.error('Failed to fetch categories:', error);
    }
  }, []);

  useEffect(() => {
    fetchCategories();
  }, [fetchCategories]);

  const buildProductSearchParams = useCallback(() => {
    const params: any = { pageNumber: page, pageSize: 15 };
    if (search) params.name = search;
    if (filterCategoryId) params.categoryId = Number.parseInt(filterCategoryId, 10);
    if (filterMinPrice) params.minPrice = Number.parseFloat(filterMinPrice);
    if (filterMaxPrice) params.maxPrice = Number.parseFloat(filterMaxPrice);
    if (filterMinStock) params.minStockQuantity = Number.parseInt(filterMinStock, 10);
    if (filterMaxStock) params.maxStockQuantity = Number.parseInt(filterMaxStock, 10);
    
    let sortByValue = 2;
    if (filterSortBy === 'name') sortByValue = 0;
    else if (filterSortBy === 'price') sortByValue = 1;
    params.sortBy = sortByValue;
    params.isDescending = filterSortDesc;
    return params;
  }, [page, search, filterCategoryId, filterMinPrice, filterMaxPrice, filterMinStock, filterMaxStock, filterSortBy, filterSortDesc]);

  const renderTableBody = () => {
    if (loading && products.length === 0) {
      return new Array(8).fill(null).map((_, i) => (
        <tr key={`table-skeleton-${i}`} className="animate-pulse border-b border-zinc-50">
          <td colSpan={5} className="h-16 bg-white dark:bg-zinc-900" />
        </tr>
      ));
    }
    if (products.length === 0) {
      return (
        <tr>
          <td colSpan={5} className="px-6 py-32 text-center text-[10px] font-bold text-zinc-300 uppercase tracking-widest italic">
            Database Empty
          </td>
        </tr>
      );
    }
    return products.map((product, idx) => (
      <InventoryRow
        key={product.id}
        product={product}
        index={(page - 1) * 15 + idx + 1}
        onSelect={setSelectedProduct}
        onDelete={handleDeleteProduct}
      />
    ));
  };

  const renderGridContent = () => {
    if (loading && products.length === 0) {
      return new Array(10).fill(null).map((_, i) => (
        <div key={`grid-skeleton-${i}`} className="h-64 bg-zinc-50 dark:bg-zinc-900/50 rounded-xl animate-pulse" />
      ));
    }
    if (products.length === 0) {
      return (
        <div className="col-span-full py-32 text-center text-[10px] font-bold text-zinc-300 uppercase tracking-widest italic">
          Database Empty
        </div>
      );
    }
    return products.map((product, idx) => (
      <InventoryCard
        key={product.id}
        product={product}
        index={(page - 1) * 15 + idx + 1}
        onSelect={setSelectedProduct}
        onDelete={handleDeleteProduct}
      />
    ));
  };

  const fetchProducts = useCallback(async () => {
    setLoading(true);
    try {
      let response;
      if (lowStockOnly) {
        response = await api.get('/inventories/low-stock', { params: { threshold: 10 } });
      } else {
        response = await api.get('/search/products', { params: buildProductSearchParams() });
      }

      if (response.data.isSuccess) {
        const items = response.data.data || [];
        const mappedItems: Product[] = items.map((item: any) => ({
          id: item.id,
          name: item.name,
          price: item.price,
          currentStock: item.currentStock || 0,
          imageUrl: item.imageUrl,
          versionStamp: item.versionStamp,
          stockVersionStamp: item.stockVersionStamp,
          categoryId: item.categoryId,
          categoryName: item.categoryName
        }));
        setProducts(mappedItems);
        setTotalPages(lowStockOnly ? 1 : (response.data.pagination?.totalPages || 1));
      }
    } catch (error) {
      console.error('Failed to fetch products:', error);
      setProducts([]);
    } finally {
      setLoading(false);
    }
  }, [page, search, filterCategoryId, filterMinPrice, filterMaxPrice, filterMinStock, filterMaxStock, filterSortBy, filterSortDesc, lowStockOnly]);

  // Sync selected product with background updates
  useEffect(() => {
    if (selectedProduct) {
      const updated = products.find(p => p.id === selectedProduct.id);
      if (updated && JSON.stringify(updated) !== JSON.stringify(selectedProduct)) {
        setSelectedProduct(updated);
      }
    }
  }, [products]);

  const handleNewProductImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setNewProductImage(file);
      const reader = new FileReader();
      reader.onloadend = () => setNewProductImagePreview(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleAddProduct = async (e: React.SyntheticEvent) => {
    e.preventDefault();
    const parsedPrice = Number.parseFloat(newProduct.price);
    const parsedStock = Number.parseInt(newProduct.stock, 10);

    if (Number.isNaN(parsedPrice) || parsedPrice < 0) {
      toast.error("Price cannot be negative.");
      return;
    }
    if (Number.isNaN(parsedStock) || parsedStock < 0) {
      toast.error("Initial stock cannot be negative.");
      return;
    }
    setIsSubmitting(true);
    try {
      const formData = new FormData();
      formData.append('name', newProduct.name);
      formData.append('price', newProduct.price);
      formData.append('initialStock', newProduct.stock);
      if (newProduct.categoryId) {
        formData.append('categoryId', newProduct.categoryId);
      }
      formData.append('businessId', currentBusinessId?.toString() || '0');

      let response;
      if (newProductImage) {
        formData.append('photoFile', newProductImage);
        response = await api.post('/inventories/photo-upload', formData);
      } else {
        response = await api.post('/inventories', formData);
      }

      if (response.data.isSuccess) {
        setIsAddModalOpen(false);
        setNewProduct({ name: '', price: '', stock: '', categoryId: '' });
        setNewProductImage(null);
        setNewProductImagePreview(null);
        fetchProducts();
      } else {
        toast.error(response.data.message || 'Failed to add product');
      }
    } catch (error: any) {
      console.error('Failed to add product:', error);
      toast.error(error.response?.data?.message || 'Failed to add product');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDeleteProduct = useCallback(async (id: number, version: string) => {
    setProductToDelete({ id, version });
  }, []);

  const confirmDeleteProduct = async () => {
    if (!productToDelete) return;
    try {
      const response = await api.delete(`/inventories/${productToDelete.id}`, { params: { version: productToDelete.version } });
      if (response.data.isSuccess) {
        setSelectedProduct(null);
        fetchProducts();
        toast.success('Product deleted successfully');
      } else {
        toast.error(response.data.message || 'Failed to delete product');
      }
    } catch (error: any) {
      console.error('Failed to delete product:', error);
      toast.error(error.response?.data?.message || 'Failed to delete product');
    } finally {
      setProductToDelete(null);
    }
  };

  useEffect(() => {
    fetchProducts();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page, searchTrigger, lowStockOnly]);

  return (
    <div className="space-y-6 w-full animate-in fade-in duration-300">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white dark:bg-zinc-900 p-6 border border-zinc-200 dark:border-zinc-700 rounded-xl shadow-sm">
        <div>
          <h1 className="text-base font-bold text-zinc-900 dark:text-zinc-100 uppercase tracking-widest">Inventory Matrix</h1>
          <p className="text-[10px] text-zinc-400 font-semibold uppercase tracking-wider mt-1">Global supply chain oversight & asset management.</p>
        </div>
        <button onClick={() => setIsAddModalOpen(true)} className="flex items-center gap-2 px-6 py-2.5 bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 rounded-lg text-[10px] font-bold uppercase tracking-widest hover:bg-zinc-800 dark:hover:bg-zinc-200 transition-all shadow-xl dark:shadow-black/20 shadow-zinc-100 w-full sm:w-auto justify-center">
          <Plus size={16} /> New Product
        </button>
      </div>

      <div className="space-y-3">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex flex-wrap items-center gap-2 flex-1 w-full">
            <div className="relative w-full sm:max-w-md flex items-center gap-2">
              <div className="relative flex-1">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400" size={16} />
                <input
                  type="text"
                  placeholder="Search products by name..."
                  value={searchInput}
                  onChange={(e) => setSearchInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      setSearch(searchInput);
                      setPage(1);
                      setSearchTrigger(prev => prev + 1);
                    }
                  }}
                  className="w-full pl-12 pr-6 py-3 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-700 rounded-xl text-xs font-semibold text-zinc-900 dark:text-zinc-100 placeholder:text-zinc-400 dark:placeholder:text-zinc-500 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 transition-all shadow-sm"
                />
              </div>
              <button
                onClick={() => {
                  setSearch(searchInput);
                  setPage(1);
                  setSearchTrigger(prev => prev + 1);
                }}
                className="px-6 py-3 bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 border border-zinc-900 dark:border-zinc-100 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all shadow-sm hover:bg-zinc-800 dark:hover:bg-zinc-200 shrink-0"
              >
                Search
              </button>
            </div>

            <button
              onClick={() => setShowFilters(!showFilters)}
              className={cn(
                "flex items-center gap-2 px-4 py-3 border rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all shadow-sm relative shrink-0",
                showFilters || hasActiveFilters
                  ? "bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 border-zinc-900 dark:border-zinc-100"
                  : "bg-white dark:bg-zinc-900 text-zinc-500 dark:text-zinc-400 border-zinc-200 dark:border-zinc-700 hover:border-zinc-400 dark:hover:border-zinc-500"
              )}
            >
              <Filter size={14} />
              Filters
              {hasActiveFilters && (
                <span className="w-1.5 h-1.5 bg-emerald-400 rounded-full absolute top-2 right-2 animate-pulse" />
              )}
              <ChevronDown size={12} className={cn("transition-transform", showFilters && "rotate-180")} />
            </button>

            <button
              onClick={() => {
                setLowStockOnly(!lowStockOnly);
                setPage(1);
              }}
              className={cn(
                "flex items-center gap-2 px-4 py-3 border rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all shadow-sm relative shrink-0",
                lowStockOnly
                  ? "bg-amber-600 border-amber-600 text-white dark:bg-amber-500 dark:border-amber-500"
                  : "bg-white dark:bg-zinc-900 text-zinc-500 dark:text-zinc-400 border-zinc-200 dark:border-zinc-700 hover:border-zinc-400 dark:hover:border-zinc-500"
              )}
            >
              <AlertCircle size={14} />
              Low Stock Only
            </button>
          </div>

          <div className="flex items-center gap-1 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-700 p-1 rounded-xl shadow-sm">
            <button
              onClick={() => setViewType('table')}
              className={cn(
                "p-2 rounded-lg transition-all",
                viewType === 'table' ? "bg-zinc-900 text-white dark:bg-zinc-100 dark:text-zinc-900" : "text-zinc-400 hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-zinc-100 hover:bg-zinc-100 dark:hover:bg-zinc-800"
              )}
            >
              <LayoutList size={18} />
            </button>
            <button
              onClick={() => setViewType('grid')}
              className={cn(
                "p-2 rounded-lg transition-all",
                viewType === 'grid' ? "bg-zinc-900 text-white dark:bg-zinc-100 dark:text-zinc-900" : "text-zinc-400 hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-zinc-100 hover:bg-zinc-100 dark:hover:bg-zinc-800"
              )}
            >
              <LayoutGrid size={18} />
            </button>
          </div>
        </div>

        {/* Filter Panel */}
        {showFilters && (
          <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-700 rounded-xl p-5 shadow-sm animate-in slide-in-from-top-2 fade-in duration-200">
            <div className="flex items-center justify-between mb-4">
              <h4 className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">Advanced Filters</h4>
              {hasActiveFilters && (
                <button
                  onClick={resetFilters}
                  className="flex items-center gap-1.5 px-3 py-1.5 text-[9px] font-bold text-zinc-500 dark:text-zinc-400 uppercase tracking-widest hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-lg transition-all border border-zinc-200 dark:border-zinc-700"
                >
                  <RotateCcw size={10} />
                  Reset All
                </button>
              )}
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
              {/* Category */}
              <div className="space-y-1.5">
                <span className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest">Category</span>
                <select
                  value={filterCategoryId}
                  onChange={(e) => { setFilterCategoryId(e.target.value); setPage(1); }}
                  className="w-full px-3 py-2 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-lg text-[10px] font-semibold text-zinc-900 dark:text-zinc-100 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 appearance-none cursor-pointer transition-all"
                >
                  <option value="">All Categories</option>
                  <CategoryOptions categories={categoryTree} />
                </select>
              </div>
              {/* Min Price */}
              <div className="space-y-1.5">
                <span className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest">Min Price</span>
                <input
                  type="number"
                  placeholder="0"
                  value={filterMinPrice}
                  onChange={(e) => { setFilterMinPrice(e.target.value); setPage(1); }}
                  className="w-full px-3 py-2 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-lg text-[10px] font-semibold text-zinc-900 dark:text-zinc-100 placeholder:text-zinc-300 dark:placeholder:text-zinc-600 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 transition-all"
                />
              </div>
              {/* Max Price */}
              <div className="space-y-1.5">
                <span className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest">Max Price</span>
                <input
                  type="number"
                  placeholder="∞"
                  value={filterMaxPrice}
                  onChange={(e) => { setFilterMaxPrice(e.target.value); setPage(1); }}
                  className="w-full px-3 py-2 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-lg text-[10px] font-semibold text-zinc-900 dark:text-zinc-100 placeholder:text-zinc-300 dark:placeholder:text-zinc-600 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 transition-all"
                />
              </div>
              {/* Min Stock */}
              <div className="space-y-1.5">
                <span className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest">Min Stock</span>
                <input
                  type="number"
                  placeholder="0"
                  value={filterMinStock}
                  onChange={(e) => { setFilterMinStock(e.target.value); setPage(1); }}
                  className="w-full px-3 py-2 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-lg text-[10px] font-semibold text-zinc-900 dark:text-zinc-100 placeholder:text-zinc-300 dark:placeholder:text-zinc-600 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 transition-all"
                />
              </div>
              {/* Max Stock */}
              <div className="space-y-1.5">
                <span className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest">Max Stock</span>
                <input
                  type="number"
                  placeholder="∞"
                  value={filterMaxStock}
                  onChange={(e) => { setFilterMaxStock(e.target.value); setPage(1); }}
                  className="w-full px-3 py-2 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-lg text-[10px] font-semibold text-zinc-900 dark:text-zinc-100 placeholder:text-zinc-300 dark:placeholder:text-zinc-600 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 transition-all"
                />
              </div>
              {/* Sort */}
              <div className="space-y-1.5">
                <span className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest">Sort By</span>
                <div className="flex gap-1">
                  <select
                    value={filterSortBy}
                    onChange={(e) => { setFilterSortBy(e.target.value as any); setPage(1); }}
                    className="flex-1 px-3 py-2 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-lg text-[10px] font-semibold text-zinc-900 dark:text-zinc-100 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 appearance-none cursor-pointer transition-all"
                  >
                    <option value="name">Name</option>
                    <option value="price">Price</option>
                    <option value="createdDate">Date</option>
                  </select>
                  <button
                    onClick={() => setFilterSortDesc(!filterSortDesc)}
                    className={cn(
                      "p-2 border rounded-lg transition-all",
                      filterSortDesc
                        ? "bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 border-zinc-900 dark:border-zinc-100"
                        : "bg-zinc-50 dark:bg-zinc-800/50 text-zinc-400 border-zinc-200 dark:border-zinc-700 hover:border-zinc-400"
                    )}
                    title={filterSortDesc ? "Descending" : "Ascending"}
                  >
                    <ArrowUpDown size={12} />
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
      <div className="relative">
        {loading && products.length > 0 && (
          <div className="absolute inset-0 bg-white/60 dark:bg-zinc-900/60 backdrop-blur-[1px] z-10 flex items-center justify-center rounded-xl">
            <Loader2 className="animate-spin text-zinc-400" size={24} />
          </div>
        )}
        {viewType === 'table' ? (
          <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-700 rounded-xl shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="border-b border-zinc-50 bg-zinc-50 dark:bg-zinc-800/50">
                    <th className="px-4 py-4 text-[10px] font-bold text-zinc-400 uppercase tracking-widest w-12 text-center">No</th>
                    <th className="px-6 py-4 text-[10px] font-bold text-zinc-400 uppercase tracking-widest">Product Entity</th>
                    <th className="px-6 py-4 text-[10px] font-bold text-zinc-400 uppercase tracking-widest text-right">MSRP (MMK)</th>
                    <th className="px-6 py-4 text-[10px] font-bold text-zinc-400 uppercase tracking-widest text-right">Stock Integrity</th>
                    <th className="px-6 py-4 text-[10px] font-bold text-zinc-400 uppercase tracking-widest text-right">Operations</th>
                  </tr>
                </thead>
                <tbody>
                  {renderTableBody()}
                </tbody>
              </table>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
            {renderGridContent()}
          </div>
        )}
      </div>

      {!loading && products.length > 0 && (
        <div className="px-6 py-4 flex items-center justify-between border-t border-zinc-50 bg-zinc-50 dark:bg-zinc-800/20 rounded-xl mt-4 border border-zinc-200 dark:border-zinc-700 shadow-sm">
          <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-widest">Page {page} of {totalPages}</p>
          <div className="flex items-center gap-1">
            <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1} className="p-2 border border-zinc-200 dark:border-zinc-700 rounded-lg bg-white dark:bg-zinc-900 disabled:opacity-20 hover:bg-zinc-100 dark:hover:bg-zinc-800 shadow-sm"><ChevronLeft size={16} /></button>
            <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages} className="p-2 border border-zinc-200 dark:border-zinc-700 rounded-lg bg-white dark:bg-zinc-900 disabled:opacity-20 hover:bg-zinc-100 dark:hover:bg-zinc-800 shadow-sm"><ChevronRight size={16} /></button>
          </div>
        </div>
      )}

      {selectedProduct && (
        <ProductDetailModal
          product={selectedProduct}
          onClose={() => setSelectedProduct(null)}
          onUpdate={fetchProducts}
          onDelete={handleDeleteProduct}
          onEditSuccess={(updated) => setSelectedProduct(updated)}
          categories={categories}
          categoryTree={categoryTree}
        />
      )}

      {/* Add Modal */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-zinc-900/40 backdrop-blur-sm" onClick={() => setIsAddModalOpen(false)} role="button" tabIndex={-1} aria-label="Close modal" onKeyDown={(e) => { if (e.key === 'Escape') setIsAddModalOpen(false); }}></div>
          <div className="relative bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-700 w-full max-w-sm rounded-2xl shadow-2xl p-8 animate-in zoom-in-98 duration-150">
            <h3 className="text-[10px] font-bold text-zinc-900 dark:text-zinc-100 uppercase tracking-widest mb-8 border-b border-zinc-50 pb-4">Onboard New Product</h3>
            <form onSubmit={handleAddProduct} className="space-y-6">
              {/* Image Upload Area */}
              <div className="space-y-2">
                <span className="block text-[9px] font-bold text-zinc-400 uppercase">Product Photo</span>
                <input type="file" ref={addImageInputRef} accept="image/*" className="hidden" onChange={handleNewProductImageSelect} />
                <div
                  onClick={() => addImageInputRef.current?.click()}
                  onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); addImageInputRef.current?.click(); } }}
                  role="button"
                  tabIndex={0}
                  className="w-full h-36 bg-zinc-50 dark:bg-zinc-900/50 border-2 border-dashed border-zinc-200 dark:border-zinc-700 rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-zinc-400 hover:bg-zinc-100 dark:bg-zinc-800/50 transition-all group overflow-hidden relative"
                >
                  {newProductImagePreview ? (
                    <>
                      <img src={newProductImagePreview} alt="Preview" className="w-full h-full object-cover" />
                      <div className="absolute inset-0 bg-black/30 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                        <span className="text-[9px] font-bold text-white uppercase tracking-widest">Change Photo</span>
                      </div>
                    </>
                  ) : (
                    <>
                      <Upload size={24} className="text-zinc-300 group-hover:text-zinc-500 transition-colors mb-2" />
                      <p className="text-[10px] font-semibold text-zinc-400 group-hover:text-zinc-600 transition-colors">Click to upload product image</p>
                      <p className="text-[9px] text-zinc-300 mt-1">Optional • JPG, PNG, WebP</p>
                    </>
                  )}
                </div>
              </div>
              <div className="space-y-2">
                <span className="block text-[9px] font-bold text-zinc-400 uppercase">Product Identification</span>
                <input required type="text" value={newProduct.name} onChange={(e) => setNewProduct({ ...newProduct, name: e.target.value })} placeholder="Legal Product Name" className="w-full px-4 py-3 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-xl text-xs font-semibold text-zinc-900 dark:text-zinc-100 placeholder:text-zinc-300 dark:placeholder:text-zinc-600 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 transition-all shadow-inner"
                />
              </div>
              <div className="space-y-2">
                <span className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest px-1">Category Assignment</span>
                <select
                  value={newProduct.categoryId}
                  onChange={(e) => setNewProduct({ ...newProduct, categoryId: e.target.value })}
                  className="w-full px-4 py-3 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-xl text-xs font-semibold text-zinc-900 dark:text-zinc-100 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 appearance-none cursor-pointer"
                >
                  <option value="">Uncategorized</option>
                  <CategoryOptions categories={categoryTree} />
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <span className="block text-[9px] font-semibold text-zinc-400 uppercase tracking-widest px-1">Unit Price</span>
                  <input required type="number" min="0" value={newProduct.price} onChange={(e) => setNewProduct({ ...newProduct, price: e.target.value })} placeholder="0.00" className="w-full px-4 py-3 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-xl text-xs font-medium text-zinc-900 dark:text-zinc-100 placeholder:text-zinc-300 dark:placeholder:text-zinc-600 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 transition-all shadow-inner" />
                </div>
                <div className="space-y-2">
                  <span className="block text-[9px] font-semibold text-zinc-400 uppercase tracking-widest px-1">Initial Stock</span>
                  <input required type="number" min="0" step="1" value={newProduct.stock} onChange={(e) => setNewProduct({ ...newProduct, stock: e.target.value })} placeholder="0" className="w-full px-4 py-3 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-xl text-xs font-medium text-zinc-900 dark:text-zinc-100 placeholder:text-zinc-350 dark:placeholder:text-zinc-650 outline-none focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 transition-all shadow-inner" />
                </div>
              </div>
              <button disabled={isSubmitting} type="submit" className="w-full py-4 bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 text-[10px] font-bold uppercase tracking-widest rounded-xl hover:bg-zinc-800 dark:hover:bg-zinc-200 transition-all shadow-xl dark:shadow-black/40 shadow-zinc-200 mt-4">
                {isSubmitting ? <Loader2 size={16} className="animate-spin m-auto" /> : 'Register Inventory Asset'}
              </button>
            </form>
          </div>
        </div>
      )}

      <ConfirmDialog
        isOpen={!!productToDelete}
        title="Delete Product"
        description="Are you sure you want to delete this product? This action cannot be undone."
        confirmText="Delete Product"
        onConfirm={confirmDeleteProduct}
        onCancel={() => setProductToDelete(null)}
        isDestructive={true}
      />
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useAuth } from '@/context/AuthContext';
import api from '@/services/api';
import { Mail, Lock, LogIn, AlertCircle, Building2, Loader2, Eye, EyeOff } from 'lucide-react';
import { UnityLogo } from '@/components/ui/UnityLogo';

export default function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { login } = useAuth();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsSubmitting(true);

    try {
      const response = await api.post('/auth/login', { email, password });
      if (response.data.isSuccess) {
        login(response.data.data);
      } else {
        setError(response.data.message || 'Invalid credentials');
      }
    } catch (err: any) {
      setError(err.response?.data?.message || 'Failed to connect to the server');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-zinc-50 dark:bg-zinc-900/50 p-6 relative overflow-hidden font-sans">
      {/* Abstract Background Detail */}
      <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-zinc-200/20 dark:bg-zinc-800/10 rounded-full blur-[120px] -mr-64 -mt-64" />
      <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-zinc-200/20 dark:bg-zinc-800/10 rounded-full blur-[120px] -ml-64 -mb-64" />

      <div className="w-full max-w-sm z-10 space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="text-center space-y-2">
          <div className="inline-flex w-14 h-14 bg-zinc-900 dark:bg-zinc-100 rounded-2xl items-center justify-center text-white dark:text-zinc-900 shadow-lg dark:shadow-black/70 shadow-zinc-200 mb-4 transform -rotate-2 hover:rotate-0 transition-transform duration-300">
            <UnityLogo size={32} />
          </div>
          <h1 className="text-2xl font-bold text-zinc-900 dark:text-zinc-100 tracking-tighter">UnityInventory</h1>
          <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-[0.2em]">Inventory Management System</p>
        </div>

        <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-700 rounded-3xl shadow-xl dark:shadow-black/70 shadow-zinc-200/50 p-10">
          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="bg-rose-50 dark:bg-rose-500/10 border border-rose-100 dark:border-rose-500/20 text-rose-600 dark:text-rose-400 px-4 py-3 rounded-xl flex items-center gap-3 animate-in fade-in zoom-in-95 duration-200">
                <AlertCircle size={16} />
                <p className="text-[11px] font-black uppercase tracking-tight">{error}</p>
              </div>
            )}

            <div className="space-y-2">
              <label className="text-[9px] font-black text-zinc-400 uppercase tracking-widest ml-1">Identity (Email)</label>
              <div className="relative group">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-300 dark:text-zinc-600 group-focus-within:text-zinc-900 dark:group-focus-within:text-zinc-100 transition-colors" size={16} />
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full pl-11 pr-4 py-3.5 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:bg-white dark:focus:bg-zinc-800 focus:border-zinc-900 dark:focus:border-zinc-500 focus:outline-none transition-all text-xs font-bold text-zinc-900 dark:text-zinc-100 placeholder:text-zinc-300 dark:placeholder:text-zinc-600 shadow-inner"
                  placeholder="name@enterprise.com"
                  required
                />
              </div>
            </div>

            <div className="space-y-2">
              <div className="flex items-center justify-between ml-1">
                <label className="text-[9px] font-black text-zinc-400 uppercase tracking-widest">Secret Key (Password)</label>
              </div>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-300 dark:text-zinc-600 group-focus-within:text-zinc-900 dark:group-focus-within:text-zinc-100 transition-colors" size={16} />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-11 pr-11 py-3.5 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-xl focus:bg-white dark:focus:bg-zinc-800 focus:border-zinc-900 dark:focus:border-zinc-500 focus:outline-none transition-all text-xs font-bold text-zinc-900 dark:text-zinc-100 placeholder:text-zinc-300 dark:placeholder:text-zinc-600 shadow-inner"
                  placeholder="••••••••"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-zinc-300 dark:text-zinc-600 hover:text-zinc-900 dark:hover:text-zinc-100 transition-colors"
                  tabIndex={-1}
                >
                  {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 py-4 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] flex items-center justify-center gap-2 hover:bg-zinc-800 dark:hover:bg-zinc-200 active:scale-[0.98] transition-all shadow-xl dark:shadow-black/70 shadow-zinc-200 disabled:opacity-50 group"
            >
              {isSubmitting ? (
                <Loader2 className="animate-spin" size={16} />
              ) : (
                <>
                  <LogIn size={14} className="group-hover:translate-x-1 transition-transform" />
                  Authenticate
                </>
              )}
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-zinc-100 dark:border-zinc-800 text-center">
            <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-widest">
              Secured Enterprise Environment
            </p>
          </div>
        </div>

        <div className="text-center space-y-4">
           <div className="flex items-center justify-center gap-4">
              <button className="text-[10px] font-black text-zinc-400 hover:text-zinc-900 dark:text-zinc-100 uppercase tracking-widest transition-colors">Privacy Policy</button>
              <div className="w-1 h-1 bg-zinc-200 dark:bg-zinc-800 rounded-full" />
              <button className="text-[10px] font-black text-zinc-400 hover:text-zinc-900 dark:text-zinc-100 uppercase tracking-widest transition-colors">IT Support</button>
           </div>
           <p className="text-[10px] text-zinc-300 font-medium tracking-tight">
             &copy; {new Date().getFullYear()} Unity Inventory CORE V2. All rights reserved.
           </p>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState, useCallback, memo } from 'react';
import api from '@/services/api';
import { cn } from '@/lib/utils';
import { 
  Search, 
  Plus, 
  FileText, 
  ChevronLeft,
  ChevronRight,
  X,
  Loader2,
  User,
  Package,
  PlusCircle,
  MinusCircle,
  Download,
  Receipt,
  ShoppingCart,
  CheckCircle2,
  LayoutList,
  LayoutGrid,
  Eye,
  Calendar,
  CreditCard,
  Hash
} from 'lucide-react';
import { MyanmarDateInput } from '@/components/ui/MyanmarDateInput';

// --- Types ---
interface SaleReport {
  id: number;
  reportDate: string;
  totalAmount: number;
  customerName: string;
  status: string;
  vouchers?: {
    id: number;
    inventoryName: string;
    quantity: number;
    sellPrice: number;
    totalPrice: number;
  }[];
}

const formatCurrency = (value: number) => {
  return `${(value || 0).toLocaleString()} MMK`;
};

const formatLocalDate = (date: Date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const formatDateToDisplay = (dateInput: string | Date) => {
  if (!dateInput) return 'N/A';
  const d = new Date(dateInput);
  if (isNaN(d.getTime())) return 'N/A';
  
  if (typeof dateInput === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(dateInput)) {
    const [year, month, day] = dateInput.split('-');
    return `${day}-${month}-${year}`;
  }
  
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return `${day}-${month}-${year}`;
};

// --- Memoized Row ---
const SaleRow = memo(({ report, index, onSelect }: { 
  report: SaleReport, 
  index: number,
  onSelect: (id: number) => void
}) => (
  <tr 
    onClick={() => onSelect(report.id)}
    className="group hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors border-b border-zinc-200 dark:border-zinc-700 last:border-0 cursor-pointer"
  >
    <td className="px-4 py-3 text-[10px] font-bold text-zinc-400 w-12 text-center">
      {index}
    </td>
    <td className="px-4 py-3">
      <div className="flex items-center gap-3">
        <div className="w-8 h-8 rounded bg-zinc-100 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 flex items-center justify-center text-zinc-400">
          <Receipt size={14} />
        </div>
        <div>
          <p className="text-xs font-bold text-zinc-900 dark:text-zinc-100 truncate tracking-tight">INV-{report.id.toString().padStart(6, '0')}</p>
          <p className="text-[10px] text-zinc-400 font-medium">{formatDateToDisplay(report.reportDate)}</p>
        </div>
      </div>
    </td>
    <td className="px-4 py-3 text-[10px] font-bold text-zinc-700 dark:text-zinc-300 tracking-tight">
      {report.customerName || 'Walk-in Customer'}
    </td>
    <td className="px-4 py-3 text-right text-xs font-bold text-zinc-900 dark:text-zinc-100">
      {formatCurrency(report.totalAmount)}
    </td>
    <td className="px-4 py-3 text-right">
      <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        <button 
          onClick={(e) => { e.stopPropagation(); onSelect(report.id); }}
          className="p-1.5 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100 transition-colors"
        >
          <Eye size={14} />
        </button>
        <button className="p-1.5 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100 transition-colors">
          <Download size={14} />
        </button>
      </div>
    </td>
  </tr>
));
SaleRow.displayName = 'SaleRow';

const SaleCard = memo(({ report, index, onSelect }: { 
  report: SaleReport, 
  index: number,
  onSelect: (id: number) => void,
}) => (
  <div 
    onClick={() => onSelect(report.id)}
    className="group bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-700 rounded-xl p-5 hover:shadow-md transition-all relative overflow-hidden flex flex-col h-full cursor-pointer"
  >
    <div className="absolute top-2 right-2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity z-10">
      <button 
        onClick={(e) => { e.stopPropagation(); onSelect(report.id); }}
        className="p-1.5 bg-white dark:bg-zinc-900/80 backdrop-blur-sm border border-zinc-200 dark:border-zinc-700 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded shadow-sm text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100 transition-colors"
      >
        <Eye size={12} />
      </button>
      <button className="p-1.5 bg-white dark:bg-zinc-900/80 backdrop-blur-sm border border-zinc-200 dark:border-zinc-700 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded shadow-sm text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100 transition-colors">
        <Download size={12} />
      </button>
