                        key={item.summaryId}
                        onClick={() => setSelectedSummary(item)}
                        className="group hover:bg-zinc-50 dark:hover:bg-zinc-800/30 transition-colors border-b border-zinc-200/50 dark:border-zinc-700/80 last:border-0 cursor-pointer text-[10px]"
