'use client';

import React, { ReactNode, useEffect, useState, useRef } from 'react';
import { Sidebar } from './Sidebar';
import { useAuth } from '@/context/AuthContext';
import { useRouter, usePathname } from 'next/navigation';
import { Bell, Plus, Search, Package, Users, FileText, BellOff, X, LayoutList, Menu } from 'lucide-react';
import { ThemeToggle } from '../ThemeToggle';
import { UnityLogo } from '../ui/UnityLogo';
import { AIChatFloating } from '@/components/AIChatFloating';


export const MainLayout = ({ children }: { children: ReactNode }) => {
  const { accessToken, isLoading } = useAuth();
  const router = useRouter();
  const pathname = usePathname();
  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const [isActionOpen, setIsActionOpen] = useState(false);
  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const [isCollapsed, setIsCollapsed] = useState(false);

  // Close mobile sidebar on route changes
  useEffect(() => {
    setIsMobileOpen(false);
  }, [pathname]);
  const notifRef = useRef<HTMLDivElement>(null);
  const actionRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isLoading && !accessToken && pathname !== '/login' && pathname !== '/select-business') {
      router.push('/login');
    }
  }, [accessToken, isLoading, router, pathname]);

  // Close dropdowns on outside click
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (notifRef.current && !notifRef.current.contains(e.target as Node)) {
        setIsNotifOpen(false);
      }
      if (actionRef.current && !actionRef.current.contains(e.target as Node)) {
        setIsActionOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-background transition-colors">
        <UnityLogo size={48} className="animate-pulse text-zinc-900 dark:text-zinc-100" />
      </div>
    );
  }

  if (pathname === '/login' || pathname === '/select-business') {
    return <>{children}</>;
  }

  if (!accessToken) {
    return (
      <div className="flex items-center justify-center h-screen bg-background transition-colors">
        <div className="w-8 h-8 border-2 border-zinc-900 dark:border-zinc-100 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  const quickActions = [
    { label: 'New Product', icon: Package, href: '/inventory', description: 'Register a new SKU' },
    { label: 'New Category', icon: LayoutList, href: '/inventory/categories', description: 'Organize your stock' },
    { label: 'New Customer', icon: Users, href: '/customers', description: 'Onboard a client' },
    { label: 'New Sale', icon: FileText, href: '/sales', description: 'Record a transaction' },
  ];

  return (
    <div className="flex min-h-screen bg-background transition-colors relative overflow-x-hidden">
      {/* Mobile Drawer Overlay Backdrop */}
      {isMobileOpen && (
        <div 
          className="fixed inset-0 bg-zinc-900/40 backdrop-blur-sm z-45 md:hidden animate-in fade-in duration-200" 
          onClick={() => setIsMobileOpen(false)}
        />
      )}

      <Sidebar 
        isMobileOpen={isMobileOpen} 
        setIsMobileOpen={setIsMobileOpen} 
        isCollapsed={isCollapsed} 
        setIsCollapsed={setIsCollapsed} 
      />
      
      <main className={`flex-1 flex flex-col min-w-0 transition-all duration-300 ease-in-out ${isCollapsed ? 'md:pl-16' : 'md:pl-64'}`}>
        {/* Compact Header */}
        <header className="h-14 bg-background border-b border-border dark:border-zinc-800 flex items-center justify-between px-4 md:px-6 sticky top-0 z-40 transition-colors">
            <div className="flex items-center gap-3">
              {/* Mobile Sidebar Hamburger Toggle */}
              <button
                onClick={() => setIsMobileOpen(true)}
                className="md:hidden p-1.5 rounded-lg text-zinc-500 hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"
                title="Open navigation menu"
              >
                <Menu size={18} />
              </button>
              
              <nav className="flex items-center text-[11px] md:text-xs font-medium text-zinc-400 truncate">
                <span className="hover:text-zinc-900 dark:hover:text-zinc-100 cursor-pointer hidden sm:inline">UnityInventory</span>
                <span className="mx-2 hidden sm:inline">/</span>
                <span className="text-zinc-900 dark:text-zinc-100 capitalize font-bold">{pathname.split('/')[1] || 'Dashboard'}</span>
              </nav>
           </div>
           
           <div className="flex items-center gap-2">
               <div className="hidden lg:flex items-center gap-2 px-3 py-1.5 bg-zinc-100 dark:bg-zinc-900 rounded-md border border-transparent hover:border-zinc-300 dark:hover:border-zinc-700 transition-all cursor-text mr-2">
                <Search size={14} className="text-zinc-400" />
                <span className="text-xs text-zinc-400 pr-12">Search...</span>
                <span className="text-[10px] font-bold text-zinc-300 dark:text-zinc-600 border border-zinc-200 dark:border-zinc-700 px-1 rounded">⌘K</span>
              </div>

              <ThemeToggle />

              {/* Notification Bell */}
              <div className="relative" ref={notifRef}>
                <button 
                  onClick={() => { setIsNotifOpen(!isNotifOpen); setIsActionOpen(false); }}
                  className={`p-1.5 rounded-md transition-all ${isNotifOpen ? 'bg-zinc-100 dark:bg-zinc-800 text-zinc-900 dark:text-zinc-100' : 'text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100 hover:bg-zinc-50 dark:hover:bg-zinc-800'}`}
                >
                  <Bell size={16} />
                </button>

                {isNotifOpen && (
                  <div className="absolute right-0 top-full mt-2 w-80 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-700 rounded-xl shadow-2xl shadow-zinc-200/50 dark:shadow-black/50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200 z-50">
                    <div className="flex items-center justify-between px-4 py-3 border-b border-zinc-100 dark:border-zinc-800">
                      <h3 className="text-xs font-semibold text-zinc-900 dark:text-zinc-100 uppercase tracking-wider">Notifications</h3>
                      <button onClick={() => setIsNotifOpen(false)} className="p-0.5 text-zinc-400 hover:text-zinc-650 rounded transition-colors">
                        <X size={14} />
                      </button>
                    </div>
                    <div className="flex flex-col items-center justify-center py-12 px-6 text-center">
                      <div className="w-12 h-12 rounded-full bg-zinc-100 dark:bg-zinc-800 dark:bg-zinc-800 flex items-center justify-center mb-3">
                        <BellOff size={20} className="text-zinc-300 dark:text-zinc-600" />
                      </div>
                      <p className="text-xs font-semibold text-zinc-500">All caught up!</p>
                      <p className="text-[10px] text-zinc-400 mt-1 leading-relaxed">
                        You have no new notifications.<br />We'll let you know when something arrives.
                      </p>
                    </div>
                    <div className="px-4 py-2.5 bg-zinc-50 dark:bg-zinc-900/50 border-t border-zinc-100 dark:border-zinc-800">
                      <p className="text-[10px] text-zinc-400 text-center font-medium">Notification center</p>
                    </div>
                  </div>
                )}
              </div>
              
              {/* Quick Action Button */}
              <div className="relative" ref={actionRef}>
                <button 
                  onClick={() => { setIsActionOpen(!isActionOpen); setIsNotifOpen(false); }}
                  className={`ml-2 flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium transition-all shadow-sm ${
                    isActionOpen 
                      ? 'bg-zinc-700 dark:bg-zinc-800 text-white' 
                      : 'bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 hover:bg-zinc-800 dark:hover:bg-zinc-200'
                  }`}
                >
                  <Plus size={14} className={`transition-transform duration-200 ${isActionOpen ? 'rotate-45' : ''}`} />
                  Action
                </button>

                {isActionOpen && (
                  <div className="absolute right-0 top-full mt-2 w-64 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-700 rounded-xl shadow-2xl shadow-zinc-200/50 dark:shadow-black/50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200 z-50">
                    <div className="px-4 py-3 border-b border-zinc-100 dark:border-zinc-800">
                      <h3 className="text-xs font-semibold text-zinc-900 dark:text-zinc-100 uppercase tracking-wider">Quick Actions</h3>
                      <p className="text-[10px] text-zinc-400 mt-0.5">Jump to a create flow</p>
                    </div>
                    <div className="py-1">
                      {quickActions.map((action) => (
                        <button
                          key={action.label}
                          onClick={() => {
                            setIsActionOpen(false);
                            router.push(action.href);
                          }}
                          className="w-full flex items-center gap-3 px-4 py-2.5 hover:bg-zinc-50 dark:hover:bg-zinc-800 transition-colors text-left group"
                        >
                          <div className="w-8 h-8 rounded-lg bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center group-hover:bg-zinc-900 dark:group-hover:bg-zinc-100 group-hover:text-white dark:group-hover:text-zinc-900 text-zinc-400 transition-all shrink-0">
                            <action.icon size={14} />
                          </div>
                          <div className="min-w-0">
                            <p className="text-xs font-semibold text-zinc-900 dark:text-zinc-100">{action.label}</p>
                            <p className="text-[10px] text-zinc-400">{action.description}</p>
                          </div>
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>
           </div>
        </header>

        {/* Content Area - Reduced Padding */}
        <div className="p-4 md:p-6 overflow-y-auto">
          {children}
        </div>
        <AIChatFloating />
      </main>
    </div>
  );
};

'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useAuth } from '@/context/AuthContext';
import api from '@/services/api';
import { 
  LayoutDashboard, 
  Package, 
  Users, 
  FileText,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Search,
  Settings,
  Command,
  Plus,
  Check,
  Building2,
  X,
  Loader2,
  LogOut,
  UserCog,
  LayoutList,
  TrendingUp
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { UnityLogo } from '@/components/ui/UnityLogo';
import { canProvisionNewBusiness } from '@/lib/accountType';

const navItems = [
  { name: 'Dashboard', href: '/dashboard', icon: LayoutDashboard },
  { name: 'Inventory', href: '/inventory', icon: Package },
  { name: 'Categories', href: '/inventory/categories', icon: LayoutList },
  { name: 'Sales Ledger', href: '/sales', icon: FileText },
  { name: 'Sales Summaries', href: '/sales/summaries', icon: TrendingUp, ownerOnly: true },
  { name: 'Customers', href: '/customers', icon: Users },
  { name: 'Team & Permissions', href: '/users', icon: UserCog, ownerOnly: true },
];

interface SidebarProps {
  isMobileOpen: boolean;
  setIsMobileOpen: (open: boolean) => void;
  isCollapsed: boolean;
  setIsCollapsed: (collapsed: boolean) => void;
}

export const Sidebar = ({ isMobileOpen, setIsMobileOpen, isCollapsed, setIsCollapsed }: SidebarProps) => {
  const pathname = usePathname();
  const { user, currentBusinessId, switchBusiness, refreshUser, logout } = useAuth();
  const [isBusinessDropdownOpen, setIsBusinessDropdownOpen] = useState(false);
  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newBusinessName, setNewBusinessName] = useState('');

  const currentBusiness = user?.businesses?.find(b => b.businessId === currentBusinessId);
  const showRegisterBusiness = user ? canProvisionNewBusiness(user.accountType) : false;

  const handleRegisterBusiness = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newBusinessName.trim()) return;

    setIsSubmitting(true);
    try {
      const response = await api.post('/business/create', {
        businessName: newBusinessName,
        subscriptionTier: 'Free',
        ownerUserId: 0 // Backend overrides
      });

      if (response.data.isSuccess) {
        await refreshUser();
        setNewBusinessName('');
        setIsRegisterModalOpen(false);
      }
    } catch (error) {
      console.error('Failed to register business:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className={cn(
      "fixed inset-y-0 left-0 z-40 flex flex-col bg-[#FAFAFA] dark:bg-zinc-950 border-r border-border dark:border-zinc-700 h-screen transition-all duration-300 ease-in-out",
      // Mobile visibility
      isMobileOpen ? "translate-x-0 w-64 z-50" : "-translate-x-full md:translate-x-0",
      // Desktop collapsed state
      isCollapsed ? "md:w-16" : "md:w-64"
    )}>
      {/* Header */}
      <div className="h-14 flex items-center px-4 border-b border-border dark:border-zinc-700 justify-between bg-background transition-colors">
        <div className="flex items-center gap-2 overflow-hidden">
          <UnityLogo size={20} className="text-zinc-900 dark:text-zinc-100 shrink-0" />
          {!isCollapsed && (
            <span className="text-sm font-bold text-zinc-900 dark:text-zinc-100 tracking-tight animate-in fade-in duration-200">UnityInventory</span>
          )}
        </div>
        <div className="flex items-center gap-1 shrink-0">
          {/* Mobile close button */}
          <button 
            onClick={() => setIsMobileOpen(false)}
            className="md:hidden p-1 text-zinc-400 hover:text-zinc-650"
            title="Close menu"
          >
            <X size={16} />
          </button>
          
          {/* Desktop collapse toggle */}
          <button 
            onClick={() => setIsCollapsed(!isCollapsed)}
            className="hidden md:block p-1 text-zinc-400 hover:text-zinc-650"
            title={isCollapsed ? "Expand sidebar" : "Collapse sidebar"}
          >
            {isCollapsed ? <ChevronRight size={14} /> : <ChevronLeft size={14} />}
          </button>
        </div>
      </div>

      {/* Business Switcher Dropdown */}
      <div className="p-3 relative">
        {!isCollapsed && (
          <label className="text-[10px] font-semibold text-zinc-400 uppercase tracking-widest px-2 mb-1 block">Active Business</label>
        )}
        <button 
          onClick={() => isCollapsed ? setIsCollapsed(false) : setIsBusinessDropdownOpen(!isBusinessDropdownOpen)}
          className={cn(
            "w-full flex items-center justify-between p-2 rounded-md border border-border dark:border-zinc-700 bg-white dark:bg-zinc-900 shadow-sm transition-all",
            isCollapsed ? "justify-center border-none shadow-none bg-transparent hover:bg-zinc-100 dark:hover:bg-zinc-800" : "hover:bg-zinc-55 dark:hover:bg-zinc-800"
          )}
          title={isCollapsed ? (currentBusiness?.businessName || 'Select Business') : undefined}
        >
          <div className="flex items-center gap-2 overflow-hidden">
            <div className="w-5 h-5 rounded bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center text-zinc-500 shrink-0">
              <UnityLogo size={14} />
            </div>
            {!isCollapsed && (
              <span className="text-xs font-medium text-zinc-700 dark:text-zinc-300 truncate">{currentBusiness?.businessName || 'Select Business'}</span>
            )}
          </div>
          {!isCollapsed && (
            <ChevronDown size={14} className={cn("text-zinc-400 transition-transform", isBusinessDropdownOpen && "rotate-180")} />
          )}
        </button>

        {isBusinessDropdownOpen && !isCollapsed && (
          <>
            <div className="fixed inset-0 z-40" onClick={() => setIsBusinessDropdownOpen(false)}></div>
            <div className="absolute left-3 right-3 mt-1 bg-white dark:bg-zinc-900 border border-border dark:border-zinc-700 rounded-md shadow-xl py-1 z-50 animate-in fade-in slide-in-from-top-2 duration-200">
              <p className="px-3 py-1.5 text-[10px] font-semibold text-zinc-400 uppercase border-b border-zinc-50 dark:border-zinc-800/50 mb-1">Your Businesses</p>
              <div className="max-h-[200px] overflow-y-auto">
                {user?.businesses?.map((business) => (
                  <button
                    key={business.businessId}
                    onClick={() => {
                      switchBusiness(business.businessId);
                      setIsBusinessDropdownOpen(false);
                    }}
                    className={cn(
                      "w-full flex items-center justify-between px-3 py-2 text-left text-xs transition-colors hover:bg-zinc-50 dark:hover:bg-zinc-800",
                      currentBusinessId === business.businessId ? "bg-zinc-50 dark:bg-zinc-800 text-zinc-900 dark:text-zinc-100 font-semibold" : "text-zinc-500"
                    )}
                  >
                    <div className="flex items-center gap-2 truncate">
                      <Building2 size={12} className={currentBusinessId === business.businessId ? "text-zinc-900 dark:text-zinc-100" : "text-zinc-300 dark:text-zinc-600"} />
                      <span className="truncate">{business.businessName}</span>
                    </div>
                    {currentBusinessId === business.businessId && (
                      <Check size={12} className="text-zinc-900 dark:text-zinc-100 shrink-0" />
                    )}
                  </button>
                ))}
              </div>
              {showRegisterBusiness && (
                <div className="border-t border-zinc-50 dark:border-zinc-800 mt-1 px-1 pt-1">
                  <button
                    type="button"
                    onClick={() => {
                      setIsBusinessDropdownOpen(false);
                      setIsRegisterModalOpen(true);
                    }}
                    className="w-full flex items-center gap-2 px-2 py-2 rounded text-xs text-zinc-900 dark:text-zinc-100 hover:bg-zinc-100 dark:hover:bg-zinc-800 font-medium transition-colors"
                  >
                    <Plus size={12} />
                    Register New Business
                  </button>
                </div>
              )}
            </div>
          </>
        )}
      </div>

      {/* Search */}
      <div className="px-3 mb-4">
        {isCollapsed ? (
          <button 
            onClick={() => setIsCollapsed(false)}
            className="w-full flex items-center justify-center py-2 bg-zinc-100 dark:bg-zinc-900/50 hover:bg-zinc-200 dark:hover:bg-zinc-800 rounded-md text-zinc-400 transition-all"
            title="Quick search..."
          >
            <Search size={14} />
          </button>
        ) : (
          <div className="relative group">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 text-zinc-400" size={14} />
            <input
              type="text"
              placeholder="Quick search..."
              className="w-full pl-8 pr-2 py-1.5 bg-zinc-100 dark:bg-zinc-900/50 border border-transparent dark:border-zinc-800 rounded-md text-xs focus:bg-white dark:focus:bg-zinc-800 focus:border-zinc-300 dark:focus:border-zinc-700 transition-all outline-none text-zinc-900 dark:text-zinc-100"
            />
          </div>
        )}
      </div>

      {/* Navigation */}
      <nav className="flex-1 px-3 space-y-0.5">
        {!isCollapsed && (
          <p className="px-2 pb-2 text-[10px] font-semibold text-zinc-400 uppercase tracking-widest">Platform</p>
        )}
        {navItems.map((item) => {
          if (item.ownerOnly && !showRegisterBusiness) return null;
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.name}
              href={item.href}
              title={isCollapsed ? item.name : undefined}
              className={cn(
                "flex items-center gap-2.5 rounded-md transition-all text-xs font-medium",
                isActive 
                  ? "bg-white dark:bg-zinc-800 text-zinc-900 dark:text-zinc-100 border border-border dark:border-zinc-700 shadow-sm" 
                  : "text-zinc-500 hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-zinc-100 hover:bg-zinc-100 dark:hover:bg-zinc-800",
                isCollapsed ? "justify-center p-2" : "px-2.5 py-1.5"
              )}
            >
              <item.icon size={16} className={cn(
                isActive ? "text-zinc-900 dark:text-zinc-100" : "text-zinc-400 dark:text-zinc-600",
                "shrink-0"
              )} />
              {!isCollapsed && <span>{item.name}</span>}
            </Link>
          );
        })}
      </nav>

      {/* Footer Profile */}
      <div className="p-3 border-t border-border dark:border-zinc-800 bg-background space-y-2 transition-colors">
        <div className={cn("flex items-center gap-2 min-w-0", isCollapsed ? "justify-center" : "")}>
          <div className="w-8 h-8 rounded-full bg-zinc-100 dark:bg-zinc-800 dark:bg-zinc-900 flex items-center justify-center text-zinc-500 dark:text-zinc-400 border border-border dark:border-zinc-700 shrink-0 text-xs font-bold">
            {user?.email?.[0]?.toUpperCase()}
          </div>
          {!isCollapsed && (
            <div className="flex-1 min-w-0">
              <p className="text-xs font-semibold text-zinc-900 dark:text-zinc-100 truncate">{user?.email?.split('@')[0]}</p>
              <p className="text-[10px] text-zinc-400 truncate uppercase tracking-tight">{user?.role}</p>
            </div>
          )}
        </div>
        <button 
          onClick={logout} 
          title={isCollapsed ? "Sign Out" : undefined}
          className={cn(
            "flex items-center gap-2 rounded-md text-xs font-medium text-zinc-500 dark:text-zinc-400 hover:text-rose-600 dark:hover:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-500/10 transition-all group",
            isCollapsed ? "justify-center p-2 w-full" : "w-full px-2.5 py-2"
          )}
        >
          <LogOut size={14} className="text-zinc-400 group-hover:text-rose-500 transition-colors shrink-0" />
          {!isCollapsed && <span>Sign Out</span>}
        </button>
      </div>

      {/* Register Business Modal */}
      {showRegisterBusiness && isRegisterModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-zinc-900/40 dark:bg-black/60" onClick={() => setIsRegisterModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-zinc-900 border border-border dark:border-zinc-700 w-full max-w-sm rounded-lg shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between p-4 border-b border-border dark:border-zinc-800">
              <h3 className="text-sm font-semibold text-zinc-900 dark:text-zinc-100 tracking-tight">Register New Business</h3>
              <button onClick={() => setIsRegisterModalOpen(false)} className="text-zinc-400 hover:text-zinc-650">
                <X size={16} />
              </button>
            </div>
            <form onSubmit={handleRegisterBusiness} className="p-4 space-y-4">
              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">Business Legal Name</label>
                <input 
                  autoFocus
                  required
                  type="text"
                  value={newBusinessName}
                  onChange={(e) => setNewBusinessName(e.target.value)}
                  placeholder="e.g. Acme Corporation"
                  className="w-full px-3 py-2 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700 rounded-md text-xs focus:ring-1 focus:ring-zinc-900 dark:focus:ring-zinc-400 focus:border-zinc-900 dark:focus:border-zinc-500 outline-none transition-all text-zinc-900 dark:text-zinc-100 placeholder:text-zinc-300 dark:placeholder:text-zinc-600"
                />
              </div>
              <button 
                disabled={isSubmitting || !newBusinessName.trim()}
                type="submit" 
                className="w-full py-2 bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 text-xs font-semibold rounded-md hover:bg-zinc-800 dark:hover:bg-zinc-200 disabled:opacity-50 transition-all flex items-center justify-center gap-2 shadow-sm"
              >
                {isSubmitting ? <Loader2 size={14} className="animate-spin" /> : 'Complete Registration'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { X, Loader2, AlertCircle } from 'lucide-react';
import { cn } from '@/lib/utils';

export interface ConfirmDialogProps {
  isOpen: boolean;
  title: string;
  description: string;
  confirmText?: string;
  cancelText?: string;
  onConfirm: () => Promise<void> | void;
  onCancel: () => void;
  isDestructive?: boolean;
}

export function ConfirmDialog({
  isOpen,
  title,
  description,
  confirmText = 'Confirm',
  cancelText = 'Cancel',
  onConfirm,
  onCancel,
  isDestructive = false
}: ConfirmDialogProps) {
  const [isLoading, setIsLoading] = useState(false);

  if (!isOpen) return null;

  const handleConfirm = async () => {
    setIsLoading(true);
    try {
      await onConfirm();
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
      <div 
        className="absolute inset-0 bg-zinc-900/40 dark:bg-black/40 backdrop-blur-sm animate-in fade-in duration-200" 
        onClick={!isLoading ? onCancel : undefined} 
      />
      <div className="relative bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95 duration-200">
        <div className="flex items-start gap-4">
          <div className={cn(
            "w-10 h-10 rounded-full flex items-center justify-center shrink-0 mt-1",
            isDestructive ? "bg-rose-100 dark:bg-rose-500/10 text-rose-600 dark:text-rose-500" : "bg-zinc-100 dark:bg-zinc-800 text-zinc-600 dark:text-zinc-400"
          )}>
            <AlertCircle size={20} />
          </div>
          <div className="flex-1">
            <h3 className="text-sm font-bold text-zinc-900 dark:text-zinc-100 uppercase tracking-widest">{title}</h3>
            <p className="text-[11px] text-zinc-500 dark:text-zinc-400 mt-2 leading-relaxed">{description}</p>
          </div>
        </div>

        <div className="flex items-center gap-3 mt-8">
          <button
            onClick={onCancel}
            disabled={isLoading}
            className="flex-1 px-4 py-2.5 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-700 text-zinc-600 dark:text-zinc-400 text-[10px] font-bold uppercase tracking-widest rounded-xl hover:bg-zinc-50 dark:hover:bg-zinc-800 transition-colors disabled:opacity-50"
          >
            {cancelText}
          </button>
          <button
            onClick={handleConfirm}
            disabled={isLoading}
            className={cn(
              "flex-1 px-4 py-2.5 text-[10px] font-bold uppercase tracking-widest rounded-xl transition-all shadow-md flex items-center justify-center gap-2 disabled:opacity-50",
              isDestructive 
                ? "bg-rose-600 hover:bg-rose-700 text-white shadow-rose-600/20" 
                : "bg-zinc-900 dark:bg-zinc-100 hover:bg-zinc-800 dark:hover:bg-zinc-200 text-white dark:text-zinc-900 shadow-black/20"
            )}
          >
            {isLoading ? <Loader2 size={14} className="animate-spin" /> : confirmText}
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useRef } from 'react';
import { Calendar } from 'lucide-react';
import { cn } from '@/lib/utils';

interface MyanmarDateInputProps {
  value: string;
  onChange: (value: string) => void;
  required?: boolean;
  className?: string;
  buttonClassName?: string;
}

const formatDateToDisplay = (dateInput: string | Date) => {
  if (!dateInput) return 'dd-mm-yyyy';
  const d = new Date(dateInput);
  if (isNaN(d.getTime())) return 'dd-mm-yyyy';

  if (typeof dateInput === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(dateInput)) {
    const [year, month, day] = dateInput.split('-');
    return `${day}-${month}-${year}`;
  }

  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return `${day}-${month}-${year}`;
};

export const MyanmarDateInput: React.FC<MyanmarDateInputProps> = ({
  value,
  onChange,
  required = false,
  className,
  buttonClassName
}) => {
  const inputRef = useRef<HTMLInputElement>(null);

  const handleButtonClick = () => {
    if (inputRef.current) {
      if (typeof inputRef.current.showPicker === 'function') {
        try {
          inputRef.current.showPicker();
        } catch (e) {
          inputRef.current.click();
        }
      } else {
        inputRef.current.click();
      }
    }
  };

  return (
    <div className={cn("relative inline-block", className)}>
      <input
        ref={inputRef}
        type="date"
        required={required}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="absolute inset-0 w-full h-full opacity-0 pointer-events-none cursor-pointer"
        tabIndex={-1}
      />
      <button
        type="button"
        onClick={handleButtonClick}
        className={cn(
          "w-full text-left pl-3 pr-8 py-2 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-700/80 rounded-lg text-[10px] font-bold text-zinc-900 dark:text-zinc-100 hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-all flex items-center justify-between",
          buttonClassName
        )}
      >
        <span>{value ? formatDateToDisplay(value) : 'dd-mm-yyyy'}</span>
        <Calendar size={12} className="text-zinc-400 shrink-0 ml-1.5" />
      </button>
    </div>
  );
};

'use client';

import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback } from 'react';
import api from '@/services/api';
import { toast } from 'sonner';

export interface ChatMessage {
  role: 'user' | 'model';
  content: string;
}

export interface SummaryParams {
  summaryType: string;
  periodStartDate: string;
  periodEndDate: string;
  totalRevenue?: number;
  averageOrderValue?: number;
  totalOrders?: number;
  totalItemsSold?: number;
}

interface AIChatContextType {
  chatMessages: ChatMessage[];
  chatLoading: boolean;
  isFloatingOpen: boolean;
  setIsFloatingOpen: (open: boolean) => void;
  sendChatMessage: (message: string) => Promise<void>;
  resetChat: () => void;
  updateSummaryParams: (params: SummaryParams) => void;
  summaryParams: SummaryParams;
}

const AIChatContext = createContext<AIChatContextType | undefined>(undefined);

const formatDateToDisplay = (dateInput: string | Date) => {
  if (!dateInput) return 'N/A';
  const d = new Date(dateInput);
  if (isNaN(d.getTime())) return 'N/A';

  if (typeof dateInput === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(dateInput)) {
    const [year, month, day] = dateInput.split('-');
    return `${day}-${month}-${year}`;
  }

  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return `${day}-${month}-${year}`;
};

const formatCurrency = (value: number) => {
  return `${(value || 0).toLocaleString()} MMK`;
};

const GENERAL_GREETING = "Hello! I'm your AI Business Analyst. How can I help you optimize your inventory, analyze client accounts, or review transaction metrics today?";

export const AIChatProvider = ({ children }: { children: ReactNode }) => {
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [chatLoading, setChatLoading] = useState(false);
  const [isFloatingOpen, setIsFloatingOpen] = useState(false);

  // Default summary parameters (current month)
  const [summaryParams, setSummaryParams] = useState<SummaryParams>(() => {
    const today = new Date();
    const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
    const formatDate = (d: Date) => {
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    };
    return {
      summaryType: 'MONTHLY',
      periodStartDate: formatDate(firstDay),
      periodEndDate: formatDate(today)
    };
  });

  // Re-generate the welcome greeting whenever the parameters or data change,
  // but only if the user hasn't started talking yet (history length <= 1)
  const getGreetingText = useCallback((params: SummaryParams) => {
    if (params.totalRevenue !== undefined) {
      const startDisplay = formatDateToDisplay(params.periodStartDate);
      const endDisplay = formatDateToDisplay(params.periodEndDate);
      return `Hello! I'm your AI Business Analyst. I've analyzed the sales summary for the period from ${startDisplay} to ${endDisplay} (${params.summaryType}). During this period:\n\n` +
        `- **Total Revenue**: ${formatCurrency(params.totalRevenue || 0)}\n` +
        `- **Average Ticket**: ${formatCurrency(params.averageOrderValue || 0)}\n` +
        `- **Total Orders**: ${params.totalOrders || 0}\n` +
        `- **Items Dispatched**: ${params.totalItemsSold || 0} items\n\n` +
        `How can I help you analyze this data or optimize your inventory operations?`;
    }
    return GENERAL_GREETING;
  }, []);

  // Set initial greeting
  useEffect(() => {
    setChatMessages([
      { role: 'model', content: getGreetingText(summaryParams) }
    ]);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Handle updating params and potentially updating the greeting
  const updateSummaryParams = useCallback((params: SummaryParams) => {
    setSummaryParams(params);

    // Only update the greeting if the user has not chatted yet
    setChatMessages((prev) => {
      if (prev.length <= 1) {
        return [{ role: 'model', content: getGreetingText(params) }];
      }
      return prev;
    });
  }, [getGreetingText]);

  const sendChatMessage = useCallback(async (messageText: string) => {
    if (!messageText.trim() || chatLoading) return;

    const userMsg = { role: 'user' as const, content: messageText };
    let currentMessages: ChatMessage[] = [];

    setChatMessages((prev) => {
      currentMessages = [...prev, userMsg];
      return currentMessages;
    });
    setChatLoading(true);

    try {
      const history = currentMessages.slice(0, -1).map(m => ({
        role: m.role === 'model' ? 'model' : 'user',
        content: m.content
      }));

      const response = await api.post('/summary/chat', {
        message: messageText,
        summaryType: summaryParams.summaryType,
        periodStartDate: summaryParams.periodStartDate,
        periodEndDate: summaryParams.periodEndDate,
        history: history
      });

      if (response.data.isSuccess && response.data.data) {
        setChatMessages([...currentMessages, { role: 'model', content: response.data.data }]);
      } else {
        toast.error('Failed to get response from AI');
      }
    } catch (err) {
      console.error(err);
      toast.error('Error contacting AI service');
    } finally {
      setChatLoading(false);
    }
  }, [chatLoading, summaryParams]);

  const resetChat = useCallback(() => {
    setChatMessages([
      { role: 'model', content: getGreetingText(summaryParams) }
    ]);
    toast.success('Chat history cleared');
  }, [getGreetingText, summaryParams]);

  return (
    <AIChatContext.Provider value={{
      chatMessages,
      chatLoading,
      isFloatingOpen,
      setIsFloatingOpen,
      sendChatMessage,
      resetChat,
      updateSummaryParams,
      summaryParams
    }}>
      {children}
    </AIChatContext.Provider>
  );
};

export const useAIChat = () => {
  const context = useContext(AIChatContext);
  if (context === undefined) {
    throw new Error('useAIChat must be used within an AIChatProvider');
  }
  return context;
};

